 import React from 'react';

 interface ButtonProps {
   variant?: 'primary' | 'secondary' | 'outline';
   size?: 'sm' | 'md' | 'lg';
   children: React.ReactNode;
   onClick?: () => void;
 }

 export const Button = ({
   variant = 'primary',
   size = 'md',
   children,
   onClick,
 }: ButtonProps) => {
   return (
     <button
       className={`rounded-md font-medium ${getVariantClasses(variant)} ${getSizeClasses(size)}`}
       onClick={onClick}
     >
       {children}
     </button>
   );
 };
